const b = $json.body || $json || {};
const service = String(b.service || '').toLowerCase();
const vmid = String(b.vmid || '');
if (service && !/^[a-z0-9][a-z0-9-]{1,62}$/.test(service)) throw new Error('Ugyldig tjenestenavn');
if (vmid && !/^\d{3,6}$/.test(vmid)) throw new Error('Ugyldig VMID');
const id = `name-map:${service || 'all'}:${vmid || 'inventory'}`;
return [{json: {job_id: id, service: service || null, vmid: vmid || null, requested_name: b.requested_name || null, requested_url: b.requested_url || null, mode: 'diagnose-og-deleger', task: 'Read-only diagnose av tjenestenavn, DNS, VLAN-tilgjengelighet og kartlenker. Ikke gjør endringer direkte.', checks: ['finn aktuell runtime-IP og DHCP-status', 'test DNS-navn fra relevante VLAN', 'test tjenesten via navn', 'søk kart og brukerlenker etter IP-adresser', 'sammenlign kartstatus med autoritative kilder'], constraints: ['bruk tjenestenavn i brukerlenker', 'ikke endre direkte fra n8n', 'send funn til lokal AI og Hermes', 'stopp ved røde driftsfunn']}}];

const item = $input.first().json;
const sd = $getWorkflowStaticData('global');
sd.jobs = sd.jobs || {};
const key = String(item.job_id || 'unknown');
const now = Date.now();
const ttl = 24 * 60 * 60 * 1000;
for (const [k,v] of Object.entries(sd.jobs)) if (now - v > ttl) delete sd.jobs[k];
if (sd.jobs[key]) return [];
sd.jobs[key] = now;
return [{json: item}];

const base = $('Lag begrenset diagnoseoppgave').first().json;
const ai = $json || {};
const aiText = typeof ai.error === 'object' ? JSON.stringify(ai.error) : String(ai.response || ai.error || 'Lokal AI svarte ikke; Hermes må klassifisere.');
return [{json: {action: 'add', tittel: 'Navn/DNS/kartdiagnose ' + base.job_id, oppgave: JSON.stringify({job_id: base.job_id, service: base.service, vmid: base.vmid, requested_name: base.requested_name, requested_url: base.requested_url, diagnose: base.task, kontroller: base.checks, begrensninger: base.constraints, lokal_ai: aiText, ai_failover: ai.error ? 'Hermes klassifiserer uten lokal AI' : 'ikke brukt'}, null, 2), kontroll: 'Rapporter konkrete DNS-svar fra relevante VLAN, tjenestesvar via navn, alle gamle IP-lenker, kartversjon og anbefalt Hermes-handling. Ikke rapporter ferdig uten les-tilbake.', godkjenning: 'ai'}}];
